def is_repeated_pattern(s):
    n = len(s)
    if n == 0:
        return False
    for divisor in range(2, n + 1):
        if n % divisor == 0:
            unit_len = n // divisor
            unit = s[:unit_len]
            if unit * divisor == s:
                return True
    return False

def is_valid_dashed_credit_card(s):
    import re
    if not re.fullmatch(r'\d{4}-\d{4}-\d{4}-\d{4}', s):
        return False
    digits = s.replace('-', '')
    total = 0
    for i in range(len(digits)):
        d = int(digits[len(digits) - 1 - i])
        if i % 2 == 1:
            d = d * 2 - 9 if d * 2 > 9 else d * 2
        total += d
    return total % 10 == 0

