def bucket_sort_by_string_length(strings, ranges):
    result = [[] for _ in ranges]
    for s in strings:
        length = len(s)
        target = next((i for i, (lo, hi) in enumerate(ranges) if lo <= length <= hi), None)
        if target is not None:
            result[target].append(s)
    return [sorted(bucket) for bucket in result]

