def is_valid_tags_with_attributes(s):
    import re
    tag_re = re.compile(r'<([a-z]+)[^<>]*>|</([a-z]+)>')
    stack = []
    pos = 0
    while pos < len(s):
        match = tag_re.match(s, pos)
        if match is None:
            return False
        opening, closing = match.group(1), match.group(2)
        if opening:
            stack.append(opening)
        else:
            if not stack or stack.pop() != closing:
                return False
        pos = match.end()
    return not stack

def time_zone_shift(time_str, hour_offset):
    hh, mm = time_str.split(':')
    minutes_total = int(hh) * 60 + int(mm) + hour_offset * 60
    days, remainder = divmod(minutes_total, 1440)
    new_h, new_m = divmod(remainder, 60)
    return (days, f'{new_h:02d}:{new_m:02d}')

def replace_nth_occurrence(s, ch, n, replacement):
    seen = 0
    for i, c in enumerate(s):
        if c == ch:
            seen += 1
            if seen == n:
                return s[:i] + replacement + s[i+1:]
    return s

